import javax.swing.SwingUtilities;

/**
 * COMPSCI 201 Final Group Project -- DKU application.
 *
 * Compile: javac *.java
 * Run:     java DKUApp
 *
 * Back-end  (state + data structures): Model, CampusGraph, CampusData,
 *                                      Node, Dijkstra
 * Front-end (Swing / Java2D):          AppFrame, CanvasPanel
 *
 * CampusData is generated by tools/make_campus_data.py and hand-editing it will
 * be overwritten; the map picture beside it is cut from the same numbers by
 * tools/make_campus_map.py. Neither script goes into the submission.
 */
public class DKUApp {

    public static void main(String[] args) {
        // Build the model first, then hand it to the view. The view never creates state.
        SwingUtilities.invokeLater(() -> {
            Model model = new Model();
            new AppFrame(model).setVisible(true);
        });
    }
}
